//! The pydantic schema of `WireEpisode`, generated by `schema/gen_schema.py`, and the
//! JSON-mode dump it drives (`model_dump(mode="json", exclude_none=...)`) for values held
//! opaquely (agent configs, messages, tools, task data, ...).
//!
//! What the dump reproduces: declared fields in order, then extras (extra="allow" models),
//! then computed fields; `exclude_none` drops `None` model fields and extras recursively
//! through nested models, never `None` values of plain dicts; `exclude=True` fields are
//! never dumped; `exclude_if` (always "when empty" in verifiers) drops empty values.

use std::collections::HashMap;
use std::sync::LazyLock;

use serde::Deserialize;

use crate::value::{Map, Value};

const SCHEMA_JSON: &str = include_str!("../schema/wire_episode.json");

#[derive(Debug, Deserialize)]
#[serde(tag = "k", rename_all = "lowercase")]
pub enum Schema {
    Any,
    None,
    Str,
    Int,
    Float,
    Bool,
    Bytes,
    Ndarray,
    Literal { values: Vec<serde_json::Value> },
    List { item: Box<Schema> },
    Dict { value: Box<Schema> },
    Union { disc: Option<String>, options: Vec<Schema> },
    Model { #[serde(rename = "ref")] name: String },
}

#[derive(Debug, Deserialize)]
pub struct Field {
    pub name: String,
    pub schema: Schema,
    #[serde(default)]
    pub exclude: bool,
    #[serde(default)]
    pub exclude_if_empty: bool,
}

#[derive(Debug, Deserialize)]
pub struct Model {
    pub fields: Vec<Field>,
    pub extra: bool,
    pub computed: Vec<String>,
}

#[derive(Debug, Deserialize)]
pub struct Schemas {
    pub root: String,
    pub models: HashMap<String, Model>,
}

pub static SCHEMAS: LazyLock<Schemas> =
    LazyLock::new(|| serde_json::from_str(SCHEMA_JSON).expect("embedded wire schema is valid"));

impl Schemas {
    pub fn model(&self, name: &str) -> &Model {
        self.models.get(name).unwrap_or_else(|| panic!("model {name} not in the wire schema"))
    }

    /// The schema of field `field` of model `model`.
    pub fn field(&self, model: &str, field: &str) -> &Schema {
        &self
            .model(model)
            .fields
            .iter()
            .find(|f| f.name == field)
            .unwrap_or_else(|| panic!("{model}.{field} not in the wire schema"))
            .schema
    }
}

/// Model names of the typed models (pydantic's parametrized names).
pub const EPISODE: &str = "Episode[WireTaskData, State, WireAgentConfig]";
pub const TRACE: &str = "Trace[WireTaskData, State, WireAgentConfig]";
pub const MESSAGE_NODE: &str = "MessageNode";

/// `model_dump(mode="json")` of a python-mode value held under `schema`.
pub fn dump_json(value: &Value, schema: &Schema, exclude_none: bool) -> Value {
    match schema {
        Schema::Model { name } => match value {
            Value::Map(map) => dump_model(map, SCHEMAS.model(name), exclude_none),
            other => plain_json(other),
        },
        Schema::List { item } => match value {
            Value::Array(items) => Value::Array(items.iter().map(|v| dump_json(v, item, exclude_none)).collect()),
            other => plain_json(other),
        },
        Schema::Dict { value: item } => match value {
            Value::Map(map) => {
                Value::Map(map.iter().map(|(k, v)| (k.clone(), dump_json(v, item, exclude_none))).collect())
            }
            other => plain_json(other),
        },
        Schema::Union { .. } if value.is_nil() => Value::Nil,
        // `X | None`: a present value is an X (which may itself be a union)
        Schema::Union { options, .. } if options.iter().filter(|o| !matches!(o, Schema::None)).count() == 1 => {
            let option = options.iter().find(|o| !matches!(o, Schema::None)).unwrap();
            dump_json(value, option, exclude_none)
        }
        Schema::Union { disc, options } => match choose(value, disc.as_deref(), options) {
            Some(option) => dump_json(value, option, exclude_none),
            None => plain_json(value),
        },
        Schema::Float => match value {
            Value::Int(i) => Value::F64(*i as f64),
            Value::UInt(u) => Value::F64(*u as f64),
            other => plain_json(other),
        },
        _ => plain_json(value),
    }
}

/// A model held as a python-mode map, dumped in JSON mode.
pub fn dump_model(map: &Map, model: &Model, exclude_none: bool) -> Value {
    let mut out = Map::with_capacity(map.len());
    for field in &model.fields {
        if field.exclude {
            continue;
        }
        let Some(value) = map.get(&field.name) else { continue };
        if (exclude_none && value.is_nil()) || (field.exclude_if_empty && !value.truthy()) {
            continue;
        }
        out.insert(field.name.clone(), dump_json(value, &field.schema, exclude_none));
    }
    if model.extra {
        for (key, value) in map {
            if model.fields.iter().any(|f| &f.name == key) || model.computed.contains(key) {
                continue;
            }
            if exclude_none && value.is_nil() {
                continue;
            }
            out.insert(key.clone(), plain_json(value));
        }
    }
    for name in &model.computed {
        if let Some(value) = map.get(name) {
            if !(exclude_none && value.is_nil()) {
                out.insert(name.clone(), plain_json(value));
            }
        }
    }
    Value::Map(out)
}

/// JSON mode of an untyped value: bytes become (UTF-8) strings.
pub fn plain_json(value: &Value) -> Value {
    match value {
        Value::Bin(b) => Value::Str(String::from_utf8_lossy(b).into_owned()),
        Value::Array(items) => Value::Array(items.iter().map(plain_json).collect()),
        Value::Map(map) => Value::Map(map.iter().map(|(k, v)| (k.clone(), plain_json(v))).collect()),
        other => other.clone(),
    }
}

fn literal_matches(values: &[serde_json::Value], value: &Value) -> bool {
    values.iter().any(|lit| match (lit, value) {
        (serde_json::Value::String(a), Value::Str(b)) => a == b,
        (serde_json::Value::Bool(a), Value::Bool(b)) => a == b,
        (serde_json::Value::Number(a), v) => a.as_f64() == v.as_f64(),
        (serde_json::Value::Null, Value::Nil) => true,
        _ => false,
    })
}

/// The union member a value was validated as: the discriminator's literal, else the type
/// of the value (a map picks the model whose fields best cover its keys).
fn choose<'a>(value: &Value, disc: Option<&str>, options: &'a [Schema]) -> Option<&'a Schema> {
    let fits = |schema: &Schema| match (schema, value) {
        (Schema::None, Value::Nil) => true,
        (Schema::Str, Value::Str(_)) => true,
        (Schema::Bool, Value::Bool(_)) => true,
        (Schema::Int, Value::Int(_) | Value::UInt(_)) => true,
        (Schema::Float, Value::F64(_) | Value::F32(_) | Value::Int(_) | Value::UInt(_)) => true,
        (Schema::Bytes, Value::Bin(_)) => true,
        (Schema::Literal { values }, v) => literal_matches(values, v),
        (Schema::List { .. }, Value::Array(_)) => true,
        (Schema::Dict { .. }, Value::Map(_)) => true,
        (Schema::Any, _) => true,
        _ => false,
    };
    if let (Some(disc), Value::Map(map)) = (disc, value) {
        if let Some(tag) = map.get(disc) {
            let found = options.iter().find(|option| match option {
                Schema::Model { name } => SCHEMAS.model(name).fields.iter().any(|f| {
                    f.name == disc && matches!(&f.schema, Schema::Literal { values } if literal_matches(values, tag))
                }),
                _ => false,
            });
            if found.is_some() {
                return found;
            }
        }
    }
    if let Value::Map(map) = value {
        // the model whose declared fields cover the most keys, fewest unknown keys
        let best = options
            .iter()
            .filter_map(|option| match option {
                Schema::Model { name } => {
                    let model = SCHEMAS.model(name);
                    let known = map
                        .keys()
                        .filter(|k| model.fields.iter().any(|f| &f.name == *k) || model.computed.contains(k))
                        .count();
                    let unknown = map.len() - known;
                    if unknown > 0 && !model.extra {
                        return Some((option, known, unknown + 1_000_000));
                    }
                    Some((option, known, unknown))
                }
                _ => None,
            })
            .min_by_key(|(_, known, unknown)| (*unknown, usize::MAX - known));
        if let Some((option, _, unknown)) = best {
            if unknown < 1_000_000 || !options.iter().any(|o| matches!(o, Schema::Dict { .. })) {
                return Some(option);
            }
        }
    }
    // smart-mode unions prefer an exact type match (an int stays an int in `int | float`)
    options
        .iter()
        .find(|o| matches!((o, value), (Schema::Int, Value::Int(_) | Value::UInt(_))))
        .or_else(|| options.iter().find(|o| fits(o)))
}
